/* Catálogo local acadêmico. Não oferece autenticação ou cobrança reais. */
(() => {
 const esc=v=>escapeAttr(String(v??''));
 const fold=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const cats=['todos','plantas','vasos','substratos','sementes','ferramentas'];
 const label=v=>v==='todos'?'Todos':v[0].toUpperCase()+v.slice(1);
 const photo='../assets/vitrine-botanica.webp';
 let selected=0,variant='',image=0;
 function cep(){return String(getStorage('customer_cep','78200000'));}
 function shipping(){const c=cep();return c.startsWith('782')?{cents:1590,days:'1 a 2 dias úteis'}:c.startsWith('78')?{cents:2490,days:'3 a 5 dias úteis'}:{cents:3990,days:'5 a 10 dias úteis'};}
 function freightForm(){return `<div class="freight"><label for="deliveryCep">CEP de entrega</label><div class="row"><input class="input" id="deliveryCep" inputmode="numeric" maxlength="9" value="${esc(cep())}" placeholder="00000-000"><button class="btn btn-outline" onclick="RaizMarket.estimate()">Calcular frete</button></div><p role="status">${money(shipping().cents/100)} · ${shipping().days}. Estimativa fictícia por faixa de CEP, sem consulta a transportadora. Frete único de demonstração, inclusive para múltiplas lojas.</p></div>`;}
 function estimate(){const c=document.getElementById('deliveryCep').value.replace(/\D/g,'');if(!/^\d{8}$/.test(c)||/^0{8}$/.test(c)){toast('Informe um CEP com oito dígitos, diferente de zero.');return;}setStorage('customer_cep',c);renderPage();}
 function init(){
   const banner=document.querySelector('.raiz-demo');
   if(banner){const details=document.createElement('details');details.className='demo-controls';const summary=document.createElement('summary');summary.innerHTML='<span>Apresentação local</span><span class="demo-controls-hint">Dados fictícios · opções e perfis</span>';details.append(summary);const content=document.createElement('div');content.className='demo-controls-content';while(banner.firstChild)content.append(banner.firstChild);details.append(content);banner.append(details);}

   if(!getStorage('catalog_v3',false)){
    state.products=state.products.map(p=>{const n=Number(p.stock)||0;return {...p,category:p.id===6?'substratos':p.category,location:p.location||'Cáceres - MT',plantType:p.category==='plantas'?(p.id===4?'Pendente':'Folhagem'):'Não se aplica',careLevel:p.category==='plantas'?(p.id===3?'Moderado':'Fácil'):'Não se aplica',variants:p.variants||[{name:'Padrão',extraCents:0,stock:Math.ceil(n/2)},{name:p.category==='plantas'||p.category==='vasos'?'Vaso maior':'Embalagem especial',extraCents:1000,stock:Math.floor(n/2)}]};});
    if(!state.products.some(p=>p.id===9))state.products.push({id:9,name:'Sementes de Girassol',category:'sementes',seller:'Raiz Forte',location:'Cáceres - MT',price:12.90,stock:30,active:true,emoji:'🌻',tag:'Cultivo',rating:0,reviews:0,description:'Pacote fictício para demonstração do catálogo de sementes.',care:'Cultivar com luz solar e regas moderadas.',size:'Pacote',plantType:'Não se aplica',careLevel:'Não se aplica',variants:[{name:'10 sementes',extraCents:0,stock:20},{name:'30 sementes',extraCents:1500,stock:10}]});
    RaizPresentation.commitLocal({products:state.products,catalog_v3:true});
   }
   // Compatibilidade: mantém carrinhos anteriores na primeira variação disponível.
   state.cart=state.cart.map(i=>{const p=productById(i.id);const v=p?.variants?.find(v=>v.name===i.variant)||p?.variants?.[0];return {...i,variant:v?.name||'',extraCents:v?.extraCents||0};});setStorage('client_cart',state.cart);
   const hash=new URLSearchParams(location.hash.slice(1));if(hash.get('product')){selected=Number(hash.get('product'));state.page='product';}else if(hash.get('seller')){state.seller=hash.get('seller');state.page='seller';}
   window.addEventListener('hashchange',()=>{const h=new URLSearchParams(location.hash.slice(1));if(h.has('product')){selected=Number(h.get('product'));variant='';image=0;state.page='product';}else if(h.has('seller')){state.seller=h.get('seller');state.page='seller';}else if(['home','catalog','orders','favorites','profile'].includes(location.hash.slice(1)))state.page=location.hash.slice(1);renderApp();});
 }
 function reviews(p){return getStorage('orders',[]).filter(o=>o.step===3&&o.rating&&o.items?.some(i=>i.productId===p.id));}
 function rating(p){const rs=reviews(p);const count=(Number(p.reviews)||0)+rs.length;return {count,value:count?((Number(p.rating)||0)*(Number(p.reviews)||0)+rs.reduce((s,r)=>s+r.rating,0))/count:0};}
 function stars(p){const r=rating(p);return `<span class="rating" aria-label="${r.value.toFixed(1)} de 5">${'★'.repeat(Math.round(r.value))}${'☆'.repeat(5-Math.round(r.value))} ${r.value.toFixed(1)} (${r.count})</span><small class="muted">Avaliações demonstrativas</small>`;}
 function cards(products){return `<div class="product-grid">${products.filter(p=>p.active!==false).map(p=>`<article class="product-card"><div class="product-image"><button class="market-photo category-${esc(p.category)}" onclick="openProduct(${Number(p.id)})" aria-label="Ver ${esc(p.name)}">${[1,4].includes(p.id)?`<img src="${photo}" alt="Ilustração botânica representativa; não é foto do produto" loading="lazy" width="640" height="420">`:`<span class="product-symbol" aria-hidden="true">${esc(p.emoji||'🌱')}</span>`}<span class="illustration-label">Imagem ilustrativa</span></button><button class="fav-btn" aria-label="Favoritar ${esc(p.name)}" aria-pressed="${state.favorites.includes(p.id)}" onclick="toggleFav(${Number(p.id)})">${state.favorites.includes(p.id)?'♥':'♡'}</button></div><div class="product-info"><span class="badge green">${p.id===1?'Mais vendido · exemplo':p.id===6?'Oferta · exemplo':esc(p.tag||p.category)}</span><h3><button class="text-button" onclick="openProduct(${Number(p.id)})">${esc(p.name)}</button></h3><button class="text-button seller" onclick="RaizMarket.seller(${Number(p.id)})">${esc(p.seller)}</button>${stars(p)}<div class="product-bottom"><div><div class="money">${money(p.price)}</div><small>${Number(p.stock)} em estoque · a partir de</small></div><button class="add-btn" aria-label="Escolher ${esc(p.name)}" onclick="openProduct(${Number(p.id)})" ${p.stock<1?'disabled':''}>＋</button></div></div></article>`).join('')}</div>`;}
 function filters(){const f=state.filters;return state.products.filter(p=>p.active!==false&&(f.category==='todos'||p.category===f.category)&&(fold([p.name,p.seller,p.description,p.category].join(' ')).includes(fold(f.search)))&&(!f.min||p.price>=Number(f.min))&&(!f.max||p.price<=Number(f.max))&&(!f.rating||rating(p).value>=Number(f.rating))&&(!f.plantType||p.plantType===f.plantType)&&(!f.careLevel||p.careLevel===f.careLevel)&&(!f.location||p.location===f.location));}
 function setFilter(key,value){state.filters[key]=value;results();}
 function results(){const out=document.getElementById('marketResults');if(out){const ps=filters();out.innerHTML=`<div class="results-heading"><strong role="status">${ps.length} produto${ps.length===1?'':'s'} encontrado${ps.length===1?'':'s'}</strong><span>Catálogo de demonstração</span></div>${ps.length?cards(ps):'<div class="empty">Nenhum produto encontrado. Ajuste ou limpe os filtros.</div>'}`;}}
 function search(value){state.filters.search=value;results();const box=document.getElementById('suggestions');const q=fold(value);const ps=state.products.filter(p=>p.active!==false&&fold(p.name+' '+p.category).includes(q)).slice(0,5);box.hidden=!q;document.getElementById('marketSearch').setAttribute('aria-expanded',String(Boolean(q)));box.innerHTML=q?cats.filter(c=>c!=='todos'&&fold(c).includes(q)).map(c=>`<button role="option" onclick="setCategory('${c}')">Categoria: ${label(c)}</button>`).join('')+ps.map(p=>`<button role="option" onclick="openProduct(${p.id})">${esc(p.name)} · ${esc(p.category)}</button>`).join('')+(ps.length?'':'<span>Nenhum produto sugerido</span>'):'';}
 function keys(event){const options=[...document.querySelectorAll('#suggestions button')];if(event.key==='Escape'){document.getElementById('suggestions').hidden=true;document.getElementById('marketSearch').setAttribute('aria-expanded','false');}else if(event.key==='ArrowDown'){event.preventDefault();options[0]?.focus();}}
 function catalog(){const f=state.filters;const select=(key,title,values)=>`<label>${title}<select class="input" onchange="RaizMarket.filter('${key}',this.value)"><option value="">Todos</option>${values.map(v=>`<option ${f[key]===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`;return `<div class="page-title"><div><span class="eyebrow">Para cultivar e cuidar</span><h1>Encontre seu próximo cultivo.</h1><p>Explore as categorias e encontre o que combina com seu espaço.</p></div></div><div class="market-search"><label for="marketSearch">Buscar produtos ou categorias</label><input class="input" id="marketSearch" role="combobox" aria-autocomplete="list" aria-controls="suggestions" aria-expanded="false" autocomplete="off" placeholder="Buscar produto..." value="${esc(f.search)}" oninput="RaizMarket.search(this.value)" onkeydown="RaizMarket.keys(event)"><div id="suggestions" role="listbox" hidden onkeydown="RaizMarket.suggestionKeys(event)"></div></div><div class="filter-line">${cats.map(c=>`<button class="chip ${f.category===c?'active':''}" onclick="setCategory('${c}')">${label(c)}</button>`).join('')}</div><div class="catalog-layout"><details class="market-filters" ${matchMedia('(min-width: 821px)').matches?'open':''}><summary>Filtrar produtos</summary><label>Preço mínimo (R$)<input class="input" type="number" min="0" step="0.01" value="${esc(f.min||'')}" onchange="RaizMarket.filter('min',this.value)"></label><label>Preço máximo (R$)<input class="input" type="number" min="0" step="0.01" value="${esc(f.max||'')}" onchange="RaizMarket.filter('max',this.value)"></label><label>Avaliação mínima<select class="input" onchange="RaizMarket.filter('rating',this.value)"><option value="">Todas</option>${[3,4,4.5,4.8].map(v=>`<option value="${v}" ${Number(f.rating)===v?'selected':''}>${v} estrelas</option>`).join('')}</select></label>${select('plantType','Tipo de planta',['Folhagem','Pendente'])}${select('careLevel','Nível de cuidado',['Fácil','Moderado'])}${select('location','Localização do vendedor',[...new Set(state.products.map(p=>p.location).filter(Boolean))])}<button class="btn btn-outline" onclick="RaizMarket.clear()">Limpar filtros</button></details><section id="marketResults"></section></div>`;}
 function product(id){selected=Number(id);variant='';image=0;state.page='product';location.hash='product='+selected;renderApp();window.scrollTo(0,0);}
 function seller(id){const p=productById(id);state.seller=p.seller;state.page='seller';location.hash='seller='+encodeURIComponent(p.seller);renderApp();window.scrollTo(0,0);}
 function detail(){const p=productById(selected);if(!p||p.active===false)return '<div class="empty">Produto indisponível.<button class="btn" onclick="go(\'catalog\')">Ver catálogo</button></div>';const choices=p.variants||[{name:'Padrão',stock:p.stock,extraCents:0}];const v=choices.find(v=>v.name===variant)||choices[0];variant=v.name;return `<button class="btn btn-outline" onclick="go('catalog')">Voltar ao catálogo</button><div class="product-detail"><section><img class="gallery-main view-${image}" src="${photo}" alt="Ilustração botânica representativa do catálogo" width="760" height="680"><div class="gallery-thumbs"><button class="btn btn-outline" aria-pressed="${image===0}" onclick="RaizMarket.image(0)">Visão completa</button><button class="btn btn-outline" aria-pressed="${image===1}" onclick="RaizMarket.image(1)">Detalhe da ilustração</button></div><p class="muted">Imagem ilustrativa já existente no projeto, compartilhada pelo catálogo. Fotografias reais de cada produto ficam para o cadastro no Supabase.</p></section><section class="card"><span class="badge green">${esc(p.category)}</span><h1>${esc(p.name)}</h1>${stars(p)}<p>${esc(p.description)}</p><button class="text-button" onclick="RaizMarket.seller(${p.id})">Visitar loja ${esc(p.seller)}</button><p>${esc(p.location||'Local não informado')}</p><label for="productVariant">Variação</label><select class="input" id="productVariant" onchange="RaizMarket.variant(this.value)">${choices.map(c=>`<option value="${esc(c.name)}" ${c.name===v.name?'selected':''}>${esc(c.name)} · ${money((Math.round(p.price*100)+(c.extraCents||0))/100)} · ${c.stock} un.</option>`).join('')}</select><p class="money">${money((Math.round(p.price*100)+(v.extraCents||0))/100)}</p><p>${Math.min(v.stock,p.stock)} unidade(s) disponível(is) nesta variação</p><label for="productQuantity">Quantidade</label><input id="productQuantity" class="input" type="number" min="1" max="${Math.min(v.stock,p.stock,99)}" value="1"><div class="market-actions"><button class="btn btn-primary" onclick="RaizMarket.add(${p.id},true)" ${!v.stock||!p.stock?'disabled':''}>Adicionar ao carrinho</button><button class="btn btn-outline" onclick="RaizMarket.buy(${p.id})" ${!v.stock||!p.stock?'disabled':''}>Comprar agora · exemplo</button></div><p class="muted">Compra rápida usa endereço e forma preferida salvos; cria uma reserva e abre a simulação. Apresentação sem login não valida identidade.</p>${freightForm()}</section></div><section class="card"><h2>Cuidados e informações</h2><p>${esc(p.care)}</p><p>Porte: ${esc(p.size)}. ${p.fragile?'Item frágil.':''}</p></section>`;}
 function storefront(){const ps=state.products.filter(p=>p.seller===state.seller&&p.active!==false);const delivered=getStorage('orders',[]).filter(o=>o.step===3&&o.rating&&o.items?.some(i=>ps.some(p=>p.id===i.productId)));return `<button class="btn btn-outline" onclick="go('catalog')">Voltar ao catálogo</button><section class="card"><h1>${esc(state.seller)}</h1><p>${esc(ps[0]?.location||'Localização não informada')}</p><p>Tempo de envio de referência: 1 a 2 dias úteis (exemplo). Não há histórico suficiente para calcular uma média real.</p><h2>Avaliações da loja</h2>${delivered.length?delivered.map(o=>`<article class="card soft"><strong>${Number(o.rating)} de 5 · pedido local entregue</strong><p>${esc(o.review||'Sem comentário.')}</p></article>`).join(''):'<p>Nenhuma avaliação de pedido entregue neste navegador.</p>'}</section><h2>Produtos desta loja</h2>${cards(ps)}`;}
 function add(id,fromDetail=false){state.products=getStorage('products',state.products);state.cart=getStorage('client_cart',[]);const p=productById(id);if(!p||p.active===false){toast('Produto indisponível.');return false;}const v=p.variants?.find(v=>v.name===(fromDetail?variant:''))||p.variants?.[0];const qty=fromDetail?Number(document.getElementById('productQuantity')?.value||1):1;const item=state.cart.find(i=>i.id===id&&(i.variant||'')===(v?.name||''));const total=state.cart.filter(i=>i.id===id).reduce((s,i)=>s+i.qty,0);if(!Number.isInteger(qty)||qty<1||qty>99||total+qty>p.stock||(item?.qty||0)+qty>Math.min(v?.stock??p.stock,99)){toast('Quantidade inválida ou estoque insuficiente.');return false;}if(item)item.qty+=qty;else state.cart.push({id,qty,variant:v?.name||'',extraCents:v?.extraCents||0});setStorage('client_cart',state.cart);updateCartBadge();toast('Item adicionado ao carrinho.');return true;}
 async function buy(id){if(state.cart.length){toast('Revise o carrinho atual antes de usar compra rápida.');openCart();return;}if(!customerAddress()||!RaizPayments.options().preferred){toast('Salve endereço e uma forma de pagamento preferida.');return;}if(!add(id,true))return;state.paymentSelection=RaizPayments.options().preferred;await confirmOrder();}
 function cart(){const sub=cartSubtotal(),ship=state.cart.length?shipping().cents/100:0;document.getElementById('cartDrawer').innerHTML=`<div class="drawer-head"><h2>Meu carrinho</h2><button class="icon-btn" onclick="closeDrawer()" aria-label="Fechar carrinho">✕</button></div><div class="drawer-body">${state.cart.map((i,index)=>{const p=productById(i.id);return `<article class="list-item"><div class="list-main"><strong>${esc(p?.name||'Produto removido')}</strong><small>${esc(i.variant)} · ${money((Number(p?.price)||0)+(Number(i.extraCents)||0)/100)} cada</small><div class="row"><button class="icon-btn" aria-label="Diminuir quantidade" onclick="RaizMarket.quantity(${index},-1)">−</button><strong>${i.qty}</strong><button class="icon-btn" aria-label="Aumentar quantidade" onclick="RaizMarket.quantity(${index},1)">＋</button><button class="btn btn-outline" onclick="RaizMarket.remove(${index})">Remover</button></div></div></article>`;}).join('')||'<p>Seu carrinho está vazio.</p>'}</div><div class="drawer-foot"><p>Subtotal: <strong>${money(sub)}</strong></p><p>Frete estimado: ${money(ship)}</p><p class="money">Total: ${money(sub+ship)}</p><button class="btn btn-primary btn-block" onclick="startCheckout()" ${!state.cart.length?'disabled':''}>Finalizar compra</button></div>`;}
 function quantity(index,delta){const i=state.cart[index];if(!i)return;const p=getStorage('products',state.products).find(p=>p.id===i.id);const v=p?.variants?.find(v=>v.name===i.variant);const total=state.cart.filter(x=>x.id===i.id).reduce((s,x)=>s+x.qty,0);if(delta>0&&(!p||i.qty+delta>Math.min(v?.stock??p.stock,99)||total+delta>p.stock)){toast('Estoque insuficiente.');return;}i.qty+=delta;if(i.qty<=0)state.cart.splice(index,1);setStorage('client_cart',state.cart);cart();updateCartBadge();}
 function remove(index){state.cart.splice(index,1);setStorage('client_cart',state.cart);cart();updateCartBadge();}
 function categoryCarousels(){
  const descriptions={plantas:'Mais vida para os seus ambientes.',vasos:'Um lugar especial para cada planta.',substratos:'A base para o seu cultivo.',sementes:'Novas possibilidades para plantar.',ferramentas:'Tudo à mão para cuidar do jardim.'};
  return `<div class="home-category-sections">${cats.slice(1).map(category=>{
   const products=state.products.filter(p=>p.active!==false&&(p.category===category||(category==='substratos'&&p.category==='insumos')));
   const id='home-category-'+category;
   return `<section class="home-category-section" aria-labelledby="${id}-title"><div class="category-section-heading"><div><span class="eyebrow">Explore por categoria</span><h2 id="${id}-title">${label(category)}</h2><p>${descriptions[category]}</p></div><button class="btn btn-outline" onclick="RaizMarket.browseCategory('${category}')">Ver ${category}</button></div>${products.length?`<div class="category-carousel-wrap"><div id="${id}" class="carousel category-carousel" aria-roledescription="carousel" aria-label="Produtos de ${label(category)}" tabindex="0">${cards(products)}</div><div class="category-carousel-footer"><span>${products.length} produto${products.length===1?'':'s'} nesta categoria</span><div class="row"><button class="btn btn-outline" data-carousel="${id}" data-direction="-1" aria-label="Produtos anteriores de ${category}" onclick="RaizMarket.slide(-1,'${id}')">Anterior</button><button class="btn btn-outline" data-carousel="${id}" data-direction="1" aria-label="Próximos produtos de ${category}" onclick="RaizMarket.slide(1,'${id}')">Próximo</button></div></div></div>`:'<p class="category-empty">Novos produtos em breve. Explore as outras categorias do catálogo.</p>'}</section>`;
  }).join('')}</div>`;
 }
 function syncCarousels(){document.querySelectorAll('.category-carousel').forEach(el=>{
  const update=()=>document.querySelectorAll('[data-carousel="'+el.id+'"]').forEach(button=>{button.disabled=Number(button.dataset.direction)<0?el.scrollLeft<=2:el.scrollLeft+el.clientWidth>=el.scrollWidth-2;});
  el.onscroll=update;update();
 });}
 window.addEventListener('resize',syncCarousels);
 function render(c){if(state.page==='catalog'){c.innerHTML=catalog();results();return true;}if(state.page==='product'){c.innerHTML=detail();return true;}if(state.page==='seller'){c.innerHTML=storefront();return true;}if(state.page==='home'){c.innerHTML=`<section class="hero-card customer-hero"><div class="customer-hero-copy"><span class="eyebrow">Seu jardim começa aqui</span><h1>Um pouco mais<br>de verde em casa.</h1><p>Encontre plantas, vasos e os cuidados que seu próximo cultivo precisa.</p><button class="btn btn-primary" onclick="go('catalog')">Explorar catálogo</button></div><img src="${photo}" alt="Composição ilustrativa de plantas em vasos" width="720" height="640"></section><div class="filter-line">${cats.slice(1).map(c=>`<button class="chip" onclick="setCategory('${c}')">${label(c)}</button>`).join('')}</div><div class="page-title"><div><h2>Destaques do catálogo</h2><p>Seleção demonstrativa. Produtos e avaliações fictícios.</p></div><div class="row"><button class="btn btn-outline" onclick="RaizMarket.slide(-1)" aria-label="Destaques anteriores">Anterior</button><button class="btn btn-outline" onclick="RaizMarket.slide(1)" aria-label="Próximos destaques">Próximo</button></div></div><section class="carousel" aria-roledescription="carousel" aria-label="Produtos em destaque" tabindex="0">${cards(state.products)}</section>${categoryCarousels()}`;requestAnimationFrame(syncCarousels);return true;}return false;}
 window.RaizMarket={init,render,cards,product,seller,search,keys,filter:setFilter,clear(){state.filters={category:'todos',search:''};renderPage();},suggestionKeys(e){const bs=[...e.currentTarget.querySelectorAll('button')];let i=bs.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();bs[(i+(e.key==='ArrowDown'?1:-1)+bs.length)%bs.length]?.focus();}if(e.key==='Escape'){e.currentTarget.hidden=true;document.getElementById('marketSearch').focus();}},variant(v){variant=v;renderPage();},image(n){image=n;renderPage();},add,buy,cart,quantity,remove,cep,shipping,estimate,freightForm,browseCategory(category){state.filters={category,search:''};go('catalog');},slide(d,id){const el=id?document.getElementById(id):document.querySelector('.carousel');if(!el)return;el.scrollBy({left:d*el.clientWidth*.8,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}};
})();
